	/**
	 * Default Constructor
	 */
    public ReviewService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new ReviewEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ReviewRepository.class) );
		this.validator		= applicationContext.getBean(ReviewValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Review
	 */
		public Review createReview( CreateReviewCommand command ) {

		Review entity = new Review();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setReviewId( command.getReviewId() );
            entity.setRating( command.getRating() );
            entity.setTitle( command.getTitle() );
            entity.setContent( command.getContent() );
            entity.setCreatedAt( command.getCreatedAt() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Review {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateReviewCommand
	 * @return		Review
	 */
	public Review updateReview( UpdateReviewCommand command ) {

		Review entity = new Review();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setReviewId( command.getReviewId() );
            entity.setRating( command.getRating() );
            entity.setTitle( command.getTitle() );
            entity.setContent( command.getContent() );
            entity.setCreatedAt( command.getCreatedAt() );
            entity.setProduct( command.getProduct() );
            entity.setCustomer( command.getCustomer() );
            entity.setOrder( command.getOrder() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Review {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteReviewCommand
	 */
	public void delete( DeleteReviewCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getReviewId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Review {0} ", id );

	}

	/**
	 * Method to retrieve the Review via ReviewFetchOneSummary
	 * @param 	summary ReviewFetchOneSummary
	 * @return 	ReviewFetchOneResponse
	 */
	public Review getReview( ReviewFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ReviewFetchOneSummary arg cannot be null" );

		Review entity = null;
		UUID id = summary.getReviewId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Review using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Reviews
	 *
	 * @return 	List<Review>
	 */
    public List<Review> getAllReview() {
		List<Review> list = projector.findAll( new FindAllReviewQuery() );
		return list;
	}

	/**
	 * assign Product on Review
	 * @param		command AssignProductToReviewCommand
	 */
	public void assignProduct( AssignProductToReviewCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignProduct(command.getReviewId(), command.getAssignment());

	}

	/**
	 * unAssign Product on Review
	 * @param		command UnAssignProductFromReviewCommand
	 */
	public void unAssignProduct( UnAssignProductFromReviewCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignProduct(command.getReviewId());
	}
	
